      </section>
      <section v-show="section === 'activity'" id="account-panel-activity" role="tabpanel" aria-labelledby="account-tab-activity"><div class="account-section-heading"><div><span class="account-eyebrow">{{ $t('admin:usersEdit.administrativeHistory') }}</span><h3>{{ $t('admin:usersEdit.recordConsideredChanges') }}</h3><p>{{ $t('admin:usersEdit.latest50RecordedAccount') }}</p></div></div><async-state v-if="!saved.history.length" state="empty" :title="$t('admin:usersEdit.noAdministrativeActionsRecorded')" :message="$t('admin:usersEdit.newChangesMadeThrough')" /><ol v-else class="account-activity"><li v-for="event in saved.history" :key="event.id"><span class="account-event-dot" aria-hidden="true" /><div><div class="account-event-heading"><h4>{{ eventTitle(event.action) }}</h4><time :datetime="event.createdAt">{{ date(event.createdAt) }}</time></div><small>{{ event.actorId ? $t('admin:usersEdit.administratorAccount', { actorId: event.actorId, interpolation: { escapeValue: false } }) : $t('admin:usersEdit.workspaceCredential') }}</small><p>{{ event.reason }}</p><ul v-if="eventFields(event.details).length"><li v-for="field in eventFields(event.details)" :key="field">{{ field }}</li></ul></div></li></ol></section>
    </template>
    <v-dialog v-model="dialog" max-width="760" :fullscreen="$vuetify.display.smAndDown" :persistent="busy" :aria-label="dialogTitle"><v-card class="account-review-dialog"><v-card-title><span class="account-eyebrow">{{ $t('admin:usersEdit.accountReview', { id: saved?.id, interpolation: { escapeValue: false } }) }}</span><h2>{{ dialogTitle }}</h2></v-card-title><v-card-text v-if="saved"><div class="account-review-person"><strong>{{ saved.name }}</strong><span>{{ saved.email }}</span></div><p class="account-review-description">{{ dialogDescription }}</p>
