      <template v-if="operation === 'password'"><v-text-field v-model="password" :label="$t('admin:usersEdit.newTemporaryPassword')" :type="showPassword ? 'text' : 'password'" autocomplete="new-password" variant="outlined" :hint="passwordHint" persistent-hint :disabled="busy"><template #append-inner><password-visibility-toggle v-model:visible="showPassword" :field="$t('admin:usersEdit.newTemporaryPassword2')" /></template></v-text-field><v-checkbox v-model="mustChangePassword" :label="$t('admin:usersEdit.requireDifferentPasswordNext')" hide-details :disabled="busy" /></template>
      <template v-if="operation === 'delete'"><v-alert type="warning" variant="tonal" class="mb-4">{{ $t('admin:usersEdit.deletionPermanentDeactivationPreserves') }}</v-alert><dl class="account-delete-counts"><div><dt>{{ $t('admin:usersEdit.pagesCreated') }}</dt><dd>{{ saved.contributionCounts.pagesCreated }}</dd></div><div><dt>{{ $t('admin:usersEdit.pagesLastAuthored') }}</dt><dd>{{ saved.contributionCounts.pagesAuthored }}</dd></div><div><dt>{{ $t('admin:usersEdit.localComments') }}</dt><dd>{{ saved.contributionCounts.comments }}</dd></div><div><dt>{{ $t('admin:usersEdit.assets') }}</dt><dd>{{ saved.contributionCounts.assets }}</dd></div></dl><v-autocomplete v-model="replaceId" v-model:search="replacementSearch" :items="replacementOptions" :label="$t('admin:usersEdit.reassignContributionAttribution')" item-title="title" item-value="id" variant="outlined" :loading="replacementLoading" :disabled="busy" no-filter clearable hide-no-data :hint="$t('admin:usersEdit.searchAnotherActiveAccount')" persistent-hint @update:search="searchReplacements" /><v-alert v-if="replacementError" type="error" variant="tonal" class="my-3">{{ replacementError }}<v-btn variant="text" @click="searchReplacements">{{ $t('admin:usersEdit.tryAgain') }}</v-btn></v-alert><v-text-field v-model="deleteConfirmation" :label="$t('admin:usersEdit.typeConfirmAccountDeletion', { id: saved.id, interpolation: { escapeValue: false } })" variant="outlined" class="mt-4" autocomplete="off" :disabled="busy" /></template>
