<script lang="ts">
import { confirmDiscard } from '../common/confirm-dialog.ts'
import { passwordPolicyMixin } from '../../helpers/password-policy.ts'
import { newPasswordIssue } from '../../../shared/security-policy.ts'
import AsyncState from '@/components/common/async-state.vue'
import PasswordVisibilityToggle from '@/components/common/password-visibility-toggle.vue'
import { accountActionTitle, accountProfileIssues, type AccountAction, type AccountProfileDraft, type AccountWorkspace } from '../../../shared/account-policy.ts'
import { fetchAccount, fetchAccountDirectory, saveAccountProfile, actOnAccount, replaceAccountPassword, deleteAccount, sendAccountWelcomeEmail, accountRequestStatus } from '../../helpers/account-api.ts'
import { getErrorMessage } from '../../helpers/root-ui-store.ts'
import { wikiStore } from '@/store/index.ts'
type Operation = AccountAction | 'profile' | 'password' | 'delete' | 'welcome'
const copy = <T,>(value: T): T => JSON.parse(JSON.stringify(value)) as T
const fieldTitles: Record<keyof AccountProfileDraft, string> = { name: 'admin:usersEdit.displayName', email: 'admin:usersEdit.emailAddress', jobTitle: 'admin:usersEdit.roleJobTitle', location: 'admin:usersEdit.location', timezone: 'admin:usersEdit.timeZone', groups: 'admin:usersEdit.groupMembership' }
const descriptions: Record<AccountAction, string> = {
  activate: 'admin:usersEdit.allowPersonSignAgain', deactivate: 'admin:usersEdit.suspendSignEndExisting', verify: 'admin:usersEdit.markSavedEmailAddress', 'require-2fa': 'admin:usersEdit.requireAuthenticatorEnrollmentDuring', 'reset-2fa': 'admin:usersEdit.clearCurrentAuthenticatorRequire', 'disable-2fa': 'admin:usersEdit.removeAccountsAuthenticatorAccount', 'end-sessions': 'admin:usersEdit.invalidateExistingSignTokens' }
export default {
  mixins: [passwordPolicyMixin],
  components: { AsyncState, PasswordVisibilityToggle },
  data() { return { saved: null as AccountWorkspace | null, draft: { name: '', email: '', location: '', jobTitle: '', timezone: 'UTC', groups: [] } as AccountProfileDraft, loading: false, loadError: '', sequence: 0, disposed: false, notice: '', section: 'profile', tabs: [{ key: 'profile', title: this.$t('admin:usersEdit.profileMembership') }, { key: 'security', title: this.$t('admin:usersEdit.signSecurity') }, { key: 'activity', title: this.$t('admin:usersEdit.activity') }], dialog: false, operation: 'profile' as Operation, reason: '', password: '', showPassword: false, mustChangePassword: true, busy: false, actionError: '', conflict: false, replacementSearch: '', replaceId: null as number | null, replacementOptions: [] as Array<{ id: number; title: string }>, replacementLoading: false, replacementError: '', replacementSequence: 0, replacementTimer: null as ReturnType<typeof setTimeout> | null, deleteConfirmation: '' } },
  computed: {
    directoryPath(): string { const from = this.$route.query.from; return typeof from === 'string' && (from === '/users' || from.startsWith('/users?')) ? from : '/users' },
    self(): boolean { return this.saved?.id === wikiStore.user.id },
    dirty(): boolean { return Boolean(this.saved && JSON.stringify({ ...this.draft, groups: [...this.draft.groups].sort((a,b) => a-b) }) !== JSON.stringify(this.saved.profile)) },
    emailChanged(): boolean { return Boolean(this.saved && this.draft.email.trim().toLowerCase() !== this.saved.email) },
    groupsChanged(): boolean { return Boolean(this.saved && JSON.stringify([...this.draft.groups].sort((a,b) => a-b)) !== JSON.stringify(this.saved.profile.groups)) },
    profileLocked(): boolean { return this.busy || this.loading || Boolean(this.loadError) || this.dialog || !this.saved?.capabilities.edit },
    actionLocked(): boolean { return this.dirty || this.busy || this.loading || Boolean(this.loadError) || this.dialog },
    profileIssues() { return accountProfileIssues(this.draft) },
    draftPermissions() { return [...new Set((this.saved?.availableGroups ?? []).filter(group => this.draft.groups.includes(group.id)).flatMap(group => group.permissions))].sort() },
    changes(): Array<{ key: string; title: string; before: string; after: string }> { if (!this.saved) return []; return (Object.keys(fieldTitles) as Array<keyof AccountProfileDraft>).flatMap(key => { const before = this.saved!.profile[key], after = this.draft[key]; if (key === 'groups' ? !this.groupsChanged : before === after) return []; const value = (input: string | number[]) => Array.isArray(input) ? input.map(id => this.saved?.availableGroups.find(group => group.id === id)?.name ?? '#' + id).join(', ') : input; return [{ key, title: this.$t(fieldTitles[key]), before: value(before), after: value(after) }] }) },
    twoFactorTitle(): string { return ({ enrolled: this.$t('admin:usersEdit.authenticatorEnrolled'), 'enrollment-required': this.$t('admin:usersEdit.enrollmentRequired'), off: this.$t('admin:usersEdit.noAccountRequirement'), 'provider-managed': this.$t('admin:usersEdit.managedProvider') })[this.saved?.twoFactor ?? 'off'] },
    twoFactorDescription(): string { return ({ enrolled: this.$t('admin:usersEdit.authenticatorEnrolledAccountsSupported'), 'enrollment-required': this.$t('admin:usersEdit.personMustCompleteAuthenticator'), off: this.$t('admin:usersEdit.accountDoesNotCurrently'), 'provider-managed': this.$t('admin:usersEdit.providerHandlesOwnSign') })[this.saved?.twoFactor ?? 'off'] },
    dialogTitle(): string { return this.operation === 'profile' ? this.$t('admin:usersEdit.reviewProfileChanges') : this.operation === 'password' ? this.$t('admin:usersEdit.replacePassword') : this.operation === 'delete' ? this.$t('admin:usersEdit.deleteAccount') : this.operation === 'welcome' ? this.$t('admin:usersEdit.sendWelcomeEmail') : this.$t(`admin:usersEdit.actionTitles.${this.operation}`) },
    dialogDescription(): string { return this.operation === 'profile' ? this.$t('admin:usersEdit.applyFollowingChangesSaved') : this.operation === 'password' ? this.$t('admin:usersEdit.setNewLocalPassword') : this.operation === 'delete' ? this.$t('admin:usersEdit.privatePagesHistoryOwned') : this.operation === 'welcome' ? this.$t('admin:usersEdit.sendConfiguredWorkspaceWelcome') : this.$t(descriptions[this.operation]) },
    endsOwnSessions(): boolean { return this.self && (this.operation === 'profile' ? this.emailChanged || this.groupsChanged : !['activate', 'verify', 'welcome', 'delete'].includes(this.operation)) },
    canConfirm(): boolean { if (this.busy || this.reason.trim().length < 3 || this.reason.trim().length > 1000) return false; if (this.operation === 'profile') return this.dirty && this.profileIssues.length === 0; if (this.operation === 'password') return !newPasswordIssue(this.password, this.passwordMinimum); if (this.operation === 'delete') return Boolean(this.replaceId && this.deleteConfirmation === String(this.saved?.id)); return true }
  },
  methods: {
    async reload() { if (this.busy || (this.dirty && !(await confirmDiscard(this.$t('admin:usersEdit.discardUnsavedProfileChanges')))) || this.busy) return; const sequence = ++this.sequence; this.loading = true; this.loadError = ''; try { const value = await fetchAccount(Number(this.$route.params.id)); if (!this.disposed && sequence === this.sequence) { this.saved = value; this.draft = copy(value.profile) } } catch (error) { if (!this.disposed && sequence === this.sequence) this.loadError = getErrorMessage(error) } finally { if (!this.disposed && sequence === this.sequence) this.loading = false } },
    reset() { if (this.saved && !this.busy && !this.dialog) this.draft = copy(this.saved.profile) },
    can(action: AccountAction): boolean { return this.saved?.capabilities.actions.includes(action) ?? false },
    open(operation: Operation) { if (this.busy || this.loading || this.loadError || (operation !== 'profile' && this.dirty)) return; this.operation = operation; this.reason = ''; this.password = ''; this.showPassword = false; this.mustChangePassword = true; this.actionError = ''; this.conflict = false; this.deleteConfirmation = ''; this.replaceId = null; this.replacementSearch = ''; this.replacementOptions = []; this.dialog = true; if (operation === 'delete') this.searchReplacements() },
    async reloadReview() { this.dialog = false; this.password = ''; await this.reload() },
    async confirm() { if (!this.saved || !this.canConfirm) return; const id = this.saved.id, operation = this.operation, ownSessions = this.endsOwnSessions; this.busy = true; this.actionError = ''; try { let next: AccountWorkspace | null = null; if (operation === 'profile') next = await saveAccountProfile(id, copy(this.draft), this.reason.trim(), this.saved.fingerprint); else if (operation === 'password') next = await replaceAccountPassword(id, this.password, this.mustChangePassword, this.reason.trim(), this.saved.fingerprint); else if (operation === 'delete') { await deleteAccount(id, this.replaceId!, this.reason.trim(), this.saved.fingerprint); this.dialog = false; this.busy = false; this.draft = copy(this.saved.profile); await this.$router.push(this.directoryPath); return } else if (operation === 'welcome') { await sendAccountWelcomeEmail(id, this.reason.trim(), this.saved.fingerprint); this.notice = this.$t('admin:usersEdit.welcomeEmailAcceptedMail'); try { next = await fetchAccount(id) } catch { this.notice += ` ${this.$t('admin:usersEdit.reloadRefreshAccountHistory')}` } } else next = await actOnAccount(id, operation, this.reason.trim(), this.saved.fingerprint); if (this.disposed) return; if (next) { this.saved = next; this.draft = copy(next.profile); if (operation !== 'welcome') this.notice = operation === 'profile' ? this.$t('admin:usersEdit.profileChangesSaved') : this.$t('admin:usersEdit.completed', { dialogTitle: this.dialogTitle, interpolation: { escapeValue: false } }) } this.dialog = false; this.password = ''; if (ownSessions) window.location.assign('/login') } catch (error) { if (!this.disposed) { this.conflict = accountRequestStatus(error) === 409; this.actionError = getErrorMessage(error) + (accountRequestStatus(error) === 0 ? ` ${this.$t('admin:usersEdit.outcomeUnconfirmedReloadAccount')}` : '') } } finally { if (!this.disposed) this.busy = false } },
    searchReplacements() { if (this.replacementTimer) clearTimeout(this.replacementTimer); const sequence = ++this.replacementSequence, search = this.replacementSearch || ''; this.replacementTimer = setTimeout(async () => { this.replacementLoading = true; this.replacementError = ''; try { const value = await fetchAccountDirectory(new URLSearchParams({ search, state: 'active', limit: '25' })); if (!this.disposed && sequence === this.replacementSequence) this.replacementOptions = value.items.filter(row => row.id !== this.saved?.id && row.id !== 2 && row.groups.every(group => this.saved?.availableGroups.some(option => option.id === group.id && option.canAssign))).map(row => ({ id: row.id, title: `${row.name} · ${row.email}` })) } catch (error) { if (!this.disposed && sequence === this.replacementSequence) this.replacementError = getErrorMessage(error) } finally { if (!this.disposed && sequence === this.replacementSequence) this.replacementLoading = false } }, 250) },
    setSection(key: string) { this.section = key; void this.$router.replace({ query: this.$route.query, hash: '#' + key }) },
    tabKey(event: KeyboardEvent, key: string) { if (!['ArrowLeft','ArrowRight','Home','End'].includes(event.key)) return; event.preventDefault(); const index = event.key === 'Home' ? 0 : event.key === 'End' ? this.tabs.length - 1 : (this.tabs.findIndex(tab => tab.key === key) + (event.key === 'ArrowRight' ? 1 : -1) + this.tabs.length) % this.tabs.length; const next = this.tabs[index]!.key; this.setSection(next); this.$nextTick(() => document.getElementById('account-tab-' + next)?.focus()) },
    initials(value: string) { return value.trim().split(/\s+/).slice(0,2).map(part => part[0]).join('').toUpperCase() },
    date(value: string) { const date = new Date(value); return Number.isNaN(date.valueOf()) ? this.$t('admin:usersEdit.notRecorded') : date.toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' }) },
    eventTitle(action: string): string { return (action in accountActionTitle ? this.$t(`admin:usersEdit.actionTitles.${action}`) : undefined) ?? ({ 'profile-updated': this.$t('admin:usersEdit.profileUpdated'), 'membership-updated': this.$t('admin:usersEdit.groupMembershipChanged'), 'group-policy-updated': this.$t('admin:usersEdit.groupAccessPolicyChanged'), 'sign-in-policy-updated': this.$t('admin:usersEdit.signProviderPolicyChanged'), 'directory-groups-synchronized': this.$t('admin:usersEdit.directoryGroupMembershipSynchronized'), 'group-deleted': this.$t('admin:usersEdit.groupMembershipEndedAfter'), 'account-created': this.$t('admin:usersEdit.accountCreated'), 'account-deleted': this.$t('admin:usersEdit.accountDeleted'), 'password-replaced': this.$t('admin:usersEdit.passwordReplaced'), 'welcome-email-requested': this.$t('admin:usersEdit.welcomeEmailRequestedOutcome'), 'welcome-email-accepted': this.$t('admin:usersEdit.welcomeEmailAcceptedMail2'), 'welcome-email-failed': this.$t('admin:usersEdit.welcomeEmailFailed') } as Record<string,string>)[action] ?? action },
    eventFields(details: Record<string,unknown>): string[] { const fields = Array.isArray(details.fields) ? details.fields.filter((value): value is string => typeof value === 'string').map(value => (value in fieldTitles ? this.$t(fieldTitles[value as keyof AccountProfileDraft]) : value)) : []; return [...fields, ...(typeof details.groupId === 'number' ? [this.$t('admin:usersEdit.group', { groupId: details.groupId, interpolation: { escapeValue: false } })] : []), ...(details.sessionsEnded === true ? [this.$t('admin:usersEdit.existingSignSessionsEnded')] : [])] },
    async canLeave(): Promise<boolean> { return !this.busy && ((!this.dirty && !(this.dialog && (this.password || this.reason))) || await confirmDiscard(this.$t('admin:usersEdit.discardUnsavedAccountChanges'))) },
    beforeUnload(event: BeforeUnloadEvent) { if (this.dirty || this.busy || (this.dialog && (this.password || this.reason))) { event.preventDefault(); event.returnValue = '' } }
  },
  watch: { '$route.hash': { immediate: true, handler(hash: string) { this.section = this.tabs.some(tab => tab.key === hash.slice(1)) ? hash.slice(1) : 'profile' } }, '$route.params.id'() { if (this.saved) this.draft = copy(this.saved.profile); this.saved = null; this.dialog = false; this.password = ''; this.notice = ''; void this.reload() }, dialog(value: boolean) { if (!value) { this.password = ''; this.replacementSequence++; if (this.replacementTimer) clearTimeout(this.replacementTimer) } } },
  mounted() { void this.reload(); window.addEventListener('beforeunload', this.beforeUnload) },
  beforeRouteLeave() { return this.canLeave() },
  beforeRouteUpdate(to, from) { return to.params.id === from.params.id || this.canLeave() },
  beforeUnmount() { this.disposed = true; this.sequence++; this.replacementSequence++; if (this.replacementTimer) clearTimeout(this.replacementTimer); this.password = ''; window.removeEventListener('beforeunload', this.beforeUnload) }
}
</script>
<style lang="scss">
