.account-tabs { display: flex; flex-wrap: wrap; gap: 4px; min-width: 0; button { background: transparent; border: 0; border-bottom: 3px solid transparent; color: var(--account-muted); padding: 10px 12px; min-height: 44px; cursor: pointer; font-size: .8125rem; font-weight: 600; &[aria-selected=true] { border-bottom-color: var(--wiki-primary-ink); color: rgb(var(--v-theme-on-surface)); } &:focus-visible { outline: 2px solid var(--wiki-primary-ink); outline-offset: -2px; } } }
.account-profile-layout { display: grid; grid-template-columns: minmax(0,1fr) 260px; gap: 16px; align-items: start; }
