.account-membership-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 8px; label { border: 1px solid var(--account-line); border-radius: var(--wiki-control-radius); display: flex; gap: 12px; align-items: flex-start; padding: 12px; cursor: pointer; min-width: 0; &.selected { border-color: var(--wiki-primary-ink); background: var(--wiki-surface-sunken); } &.locked { cursor: default; } input { margin-top: 3px; width: 18px; height: 18px; flex-shrink: 0; accent-color: rgb(var(--v-theme-primary)); } span { min-width: 0; } strong { display: block; font-size: .8125rem; font-weight: 600; overflow-wrap: anywhere; } small { display: block; font-size: .75rem; margin-top: 4px; color: var(--account-muted); } } }
.account-permissions { margin-top: 12px; summary { font-size: .8125rem; cursor: pointer; min-height: 44px; padding-block: 12px; } >ul { display: flex; flex-wrap: wrap; gap: 8px 16px; padding: 8px 0 0; list-style: none; font-size: .75rem; overflow-wrap: anywhere; } p { font-size: .8125rem; margin-top: 8px; color: var(--account-muted); } }
.account-context-card { dl { margin-top: 12px; display: grid; gap: 12px; } dt { font-size: .75rem; color: var(--account-muted); margin-bottom: 4px; } dd { margin: 0; font-size: .8125rem; overflow-wrap: anywhere; } >p { margin: 12px 0 0; font-size: .75rem; line-height: 1.6; color: var(--account-muted); } .account-contributions >div { display: flex; justify-content: space-between; gap: 12px; align-items: center; dt { margin: 0; } dd { font-variant-numeric: tabular-nums; } } }
