.account-footnote { font-size: .75rem !important; line-height: 1.6; color: var(--account-muted); margin: 12px 0 0; a { color: var(--wiki-primary-ink); text-underline-offset: 3px; } }
.account-draft-bar { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 12px; padding: 16px; margin-top: 16px; border: 1px solid var(--account-line); border-radius: var(--wiki-panel-radius); background: var(--wiki-surface-raised); >div:last-child { display: flex; flex-wrap: wrap; gap: 8px; } strong { font-size: .8125rem; display: block; font-weight: 600; } span { display: block; font-size: .75rem; color: var(--account-muted); margin-top: 4px; } }
.account-section-heading { display: flex; flex-wrap: wrap; gap: 12px; justify-content: space-between; align-items: center; padding-bottom: 16px; h3 { font-size: 1.125rem; margin: 4px 0 8px; font-weight: 650; } p { font-size: .8125rem; max-width: 70ch; line-height: 1.6; color: var(--account-muted); margin: 0; } }
.account-security-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 12px; }
.account-security-card { display: flex; flex-direction: column; align-items: flex-start; padding: 16px; border: 1px solid var(--account-line); border-radius: var(--wiki-panel-radius); background: var(--wiki-surface-raised); min-width: 0; >.v-icon { margin-bottom: 8px; color: var(--account-muted); } h4 { font-size: 1rem; font-weight: 650; margin: 4px 0 8px; } >p { font-size: .8125rem; line-height: 1.6; color: var(--account-muted); margin: 0 0 12px; overflow-wrap: anywhere; } >small { font-size: .75rem; color: var(--account-muted); line-height: 1.6; margin-bottom: 12px; } >.v-btn,.account-security-actions { margin-top: auto; } .account-footnote { margin: 12px 0 0; } }
.account-security-actions { display: flex; gap: 8px; align-items: flex-start; flex-wrap: wrap; .v-btn { max-width: 100%; } }
.account-deletion { margin-top: 16px; border-top: 1px solid var(--account-line); padding: 16px 0; display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 16px; h4 { font-size: 1rem; font-weight: 650; margin: 4px 0 8px; } p { font-size: .8125rem; color: var(--account-muted); line-height: 1.6; margin: 0; max-width: 70ch; } }
.account-activity { list-style: none; padding: 0; margin: 0; >li { display: grid; grid-template-columns: 12px minmax(0,1fr); gap: 12px; padding: 16px 0; border-bottom: 1px solid var(--account-line); small { font-size: .75rem; color: var(--account-muted); display: block; margin-top: 6px; } p { font-size: .8125rem; white-space: pre-wrap; overflow-wrap: anywhere; line-height: 1.6; margin: 12px 0 0; } ul { list-style: none; padding: 0; display: flex; flex-wrap: wrap; gap: 8px; margin-top: 12px; li { font-size: .75rem; padding: 4px 8px; border-radius: 4px; background: var(--wiki-surface-sunken); overflow-wrap: anywhere; } } } }
.account-event-dot { height: 7px; width: 7px; margin-top: 8px; border-radius: 50%; background: var(--wiki-primary-ink); }
.account-event-heading { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 8px; h4 { font-size: .9375rem; font-weight: 650; overflow-wrap: anywhere; } time { font-size: .75rem; color: var(--account-muted); } }
.account-review-dialog { max-height: 90dvh; background: var(--wiki-surface-raised); .v-card-title { white-space: normal; padding: 20px 20px 12px; h2 { font-size: 1.125rem; margin-top: 4px; font-weight: 650; overflow-wrap: anywhere; } } .v-card-text { padding: 8px 20px 20px; overflow-y: auto; } .v-card-actions { padding: 12px 16px; border-top: 1px solid var(--account-line); flex-wrap: wrap; } }
.account-review-person { display: flex; flex-direction: column; gap: 4px; margin: 0 0 12px; strong { font-size: 1rem; font-weight: 650; overflow-wrap: anywhere; } span { font-size: .8125rem; color: var(--account-muted); overflow-wrap: anywhere; } }
.account-review-description { font-size: .8125rem; color: var(--account-muted); line-height: 1.6; margin-bottom: 16px; }
.account-review-changes { display: grid; gap: 12px; border-block: 1px solid var(--account-line); padding: 16px 0; dt { font-size: .75rem; color: var(--account-muted); margin-bottom: 8px; } dd { display: flex; gap: 12px; align-items: center; font-size: .8125rem; overflow-wrap: anywhere; margin: 0; >span,>strong { flex: 1; min-width: 0; } >span { color: var(--account-muted); } strong { font-weight: 600; } } }
